database.supabaseBuckets:
GRANT USAGE ON SCHEMA storage TO phisc_ro;
GRANT SELECT ON storage.buckets TO phisc_ro;
CREATE POLICY phisc_ro_read_buckets ON storage.buckets FOR SELECT TO phisc_ro USING (true);

database.pg14Steps:
BEGIN;
GRANT CREATE ON SCHEMA public TO your_migration_role;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
COMMIT;

database.largeObjectCheck:
SELECT l.oid FROM pg_largeobject_metadata l
WHERE l.lomowner = 'phisc_ro'::regrole
   OR EXISTS (SELECT 1 FROM aclexplode(l.lomacl) a
              WHERE a.privilege_type IN ('SELECT', 'UPDATE')
                AND (a.grantee = 0 OR a.grantee = 'phisc_ro'::regrole));
SHOW lo_compat_privileges;
